 @GameTest(template="elevator2_shaft",batch="elevator3",timeoutTicks=80)
 public static void eight_audible_chimes_and_off_preserve_legacy_cues_and_saved_selection(GameTestHelper h){
  var d=drive(h,new BlockPos(5,2,5),Direction.SOUTH);var ids=new HashSet<net.minecraft.resources.ResourceLocation>();
  for(var preset:CabinConfiguration.Chime.values()){
   check(d.configureModel("chime",preset.name()),"Server accepts chime "+preset);
   var saved=new ModelCabinController(d);saved.load(d.model().save());check(saved.config().chime()==preset,"Controller NBT preserves "+preset);
   var event=ElevatorSounds.modelCue(preset);
   if(preset==CabinConfiguration.Chime.NONE){check(event==null,"Off has no sound event");continue;}
   check(event!=null,"Audible cue registered");var id=net.minecraft.core.registries.BuiltInRegistries.SOUND_EVENT.getKey(event);check(id!=null&&ids.add(id),"Each audible preset has its own registered event");
   if(preset==CabinConfiguration.Chime.OTIS)check(event==ElevatorSounds.cue(true,true),"Original Otis event unchanged");
   if(preset==CabinConfiguration.Chime.SCHINDLER_HT)check(event==ElevatorSounds.cue(true,false),"Original Schindler event unchanged");
   ElevatorSounds.playModel(h.getLevel(),d.getBlockPos(),preset);
  }
  check(ids.size()==8,"Two original cues plus six additions");h.succeed();
 }
 @GameTest(template="elevator2_shaft",batch="elevator3",timeoutTicks=80)
 public static void all_twenty_cabins_have_registered_entities_and_real_floor_collision(GameTestHelper h){
  var d=drive(h,new BlockPos(5,2,5),Direction.SOUTH);int count=0;
  for(int size=3;size<=3;size++)for(var variant:CabinConfiguration.Variant.values()){
   prepare(h,d,size,variant);var e=d.model().entity();check(e!=null&&e.getType()==ElevatorRegistry.MODEL_CABIN.get(),"Own cabin entity is used");check(!CabinGeometry.body(e.configuration()).isEmpty(),"Body mesh exists");
   Vec3 inside=e.world(size/2.0,.125,size*.3);var box=new AABB(inside.x-.25,inside.y,inside.z-.25,inside.x+.25,inside.y+1.8,inside.z+.25);
   var motion=net.minecraft.world.entity.Entity.collideBoundingBox(null,new Vec3(0,-.25,0),box,h.getLevel(),List.of());check(Math.abs(motion.y)<.001,"Native collision supports the cabin floor: "+size+"/"+variant+" / "+motion);
   check(d.deactivateModel(),"Empty cabin deactivates");count++;
  }
  check(count==CabinConfiguration.Variant.values().length,"All primary configurations tested");check(!d.configureModel("size","2"),"New cabins refuse sizes other than 3x3");prepare(h,d,3,CabinConfiguration.Variant.SOLID);int parts=0;var origin=d.getBlockPos();for(int x=-8;x<=8;x++)for(int z=-8;z<=8;z++)for(int y=1;y<=27;y++){var cell=origin.offset(x,y,z);if(h.getLevel().getBlockEntity(cell) instanceof ModelLandingEntity be&&origin.equals(be.markerDrive()))parts++;}check(parts==27,"Exactly three 3x3 landings remain at the three floors: "+parts);check(d.deactivateModel(),"Cabin deactivates");h.succeed();
 }
 @GameTest(template="elevator2_shaft",batch="elevator3",timeoutTicks=100)
 public static void model_mounts_spawn_persistence_and_door_colliders_work_in_all_directions(GameTestHelper h){
  int i=0;for(var mount:Direction.Plane.HORIZONTAL){var d=drive(h,new BlockPos(6+(i%2)*10,2,6+(i/2)*10),mount);prepare(h,d,3,CabinConfiguration.Variant.SOLID);check(d.configureModel("primary","5")&&d.configureModel("front","GLASS"),"Nondefault appearance synchronizes to the active model and matching landings");var e=d.model().entity();var feet=e.world(1.5,.13,.65);var box=new AABB(feet.x-.2,feet.y,feet.z-.2,feet.x+.2,feet.y+1.8,feet.z+.2);var back=e.facing();var attempted=new Vec3(-back.getStepX()*.8,0,-back.getStepZ()*.8);var blocked=net.minecraft.world.entity.Entity.collideBoundingBox(null,attempted,box,h.getLevel(),List.of());check(blocked.horizontalDistance()<.79,"Closed door collision in mount "+mount);
   var tag=e.saveWithoutId(new net.minecraft.nbt.CompoundTag());var loaded=new ModelCabinEntity(ElevatorRegistry.MODEL_CABIN.get(),h.getLevel());loaded.load(tag);check(loaded.configuration().equals(e.configuration())&&loaded.facing()==e.facing(),"Dedicated cabin settings and orientation survive NBT reload");
   var wire=new net.minecraft.network.RegistryFriendlyByteBuf(io.netty.buffer.Unpooled.buffer(),h.getLevel().registryAccess());var values=e.getEntityData().getNonDefaultValues();check(values!=null,"Spawn data exists");var packet=new net.minecraft.network.protocol.game.ClientboundSetEntityDataPacket(e.getId(),values);net.minecraft.network.protocol.game.ClientboundSetEntityDataPacket.STREAM_CODEC.encode(wire,packet);var decoded=net.minecraft.network.protocol.game.ClientboundSetEntityDataPacket.STREAM_CODEC.decode(wire);var receiver=new ModelCabinEntity(ElevatorRegistry.MODEL_CABIN.get(),h.getLevel());receiver.getEntityData().assignValues(decoded.packedItems());check(receiver.configuration().equals(e.configuration())&&receiver.facing()==e.facing(),"Cabin metadata survives actual registry-aware network codec");wire.release();check(d.deactivateModel(),"Empty cabin can be deactivated");i++;}
  h.succeed();
 }
 @GameTest(template="elevator2_shaft",batch="elevator3",timeoutTicks=700)
 public static void moving_controller_nbt_reload_rebinds_the_existing_cabin_uuid(GameTestHelper h){
  var d=drive(h,new BlockPos(5,2,5),Direction.SOUTH);int base=d.anchor().getY();prepare(h,d,3,CabinConfiguration.Variant.SOLID);var original=d.model().entity();var uuid=original.getUUID();d.requestFloor(base+12);ElevatorDriveEntity[] current={d};boolean[] replaced={false};
  h.onEachTick(()->{var live=current[0];var state=live.model().state();if(state==null)return;if(state.state()==CabinMotionController.State.FAULT)throw new GameTestAssertException(state.fault());
   if(state.state()==CabinMotionController.State.MOVING&&state.y()>base+2&&!replaced[0]){var tag=live.saveWithFullMetadata(h.getLevel().registryAccess());var position=live.getBlockPos();var block=live.getBlockState();h.getLevel().removeBlockEntity(position);var loaded=new ElevatorDriveEntity(position,block);loaded.loadWithComponents(tag,h.getLevel().registryAccess());h.getLevel().setBlockEntity(loaded);loaded.onLoad();current[0]=loaded;replaced[0]=true;}
   if(replaced[0]&&state.state()==CabinMotionController.State.DOORS_OPEN&&Math.abs(state.y()-base-12)<.001){check(live.model().entity()!=null&&live.model().entity().getUUID().equals(uuid),"Reload uses the original entity, not a duplicate cabin");check(h.getLevel().getEntitiesOfClass(ModelCabinEntity.class,original.getBoundingBox().inflate(1)).size()==1,"Exactly one cabin remains");h.succeed();}
  });
 }
 @GameTest(template="elevator2_shaft",batch="elevator3",timeoutTicks=700)
 public static void broken_model_guide_faults_without_teleport_and_repairs_resume_safely(GameTestHelper h){
  var d=drive(h,new BlockPos(5,2,5),Direction.SOUTH);int base=d.anchor().getY();prepare(h,d,3,CabinConfiguration.Variant.SOLID);d.requestFloor(base+12);boolean[] broken={false},repaired={false};double[] stopped={0};
  h.onEachTick(()->{var s=d.model().state();if(s==null)return;if(s.state()==CabinMotionController.State.MOVING&&s.y()>base+2&&!broken[0]){h.getLevel().setBlock(d.getBlockPos().above(7),Blocks.AIR.defaultBlockState(),3);broken[0]=true;}
   if(broken[0]&&s.state()==CabinMotionController.State.FAULT&&!repaired[0]){check(s.y()<base+12,"Broken rail stops before destination");stopped[0]=s.y();check(d.model().entity().doorsClosed(),"Fault keeps cabin doors closed");var p=d.getBlockPos().above(7);h.getLevel().setBlock(p,ElevatorRegistry.GUIDE_RAIL.get().defaultBlockState().setValue(ElevatorPartBlock.FACING,Direction.SOUTH),3);d.rescan();check(d.retry(),"Repair allows retry");check(Math.abs(d.model().state().y()-stopped[0])<.0001,"Retry does not teleport the cabin");repaired[0]=true;}
   if(repaired[0]&&s.state()==CabinMotionController.State.DOORS_OPEN&&Math.abs(s.y()-base-12)<.001)h.succeed();
  });
  h.runAtTickTime(650,()->{throw new GameTestAssertException("Recovery incomplete: broken="+broken[0]+", repaired="+repaired[0]+", state="+d.model().state()+", rails="+d.railWarning());});
 }
 @GameTest(template="elevator2_shaft",batch="elevator3",timeoutTicks=1200)
 public static void model_trip_moves_riders_opens_only_selected_sides_and_persists_motion(GameTestHelper h){
  var d=drive(h,new BlockPos(9,2,5),Direction.EAST);int base=d.anchor().getY();check(d.configureModel("rearEnabled","true"),"Rear enabled");check(d.modelPolicy(base+12,false,true,0,2),"Rear-only floor policy");check(d.configureModel("railMount","true")&&d.configureModel("size","3")&&d.configureModel("variant","REAR_PANORAMIC"),"Through cabin configured");/* DEV17: a through cabin needs its guide rail beside it, not behind a doorway. Size changes re-apply the mount, so rotate last. */check(d.configureModel("rotate","clockwise"),"Rotate so the rail is beside the cabin");{var installer=FakePlayerFactory.getMinecraft(h.getLevel());for(var f:d.floorList())check(d.installModelLanding(installer,f.y()),"Landing installed: "+d.model().warning());}check(d.activateModel(),"Dedicated entity activated: "+d.model().warning());var e=d.model().entity();var point=e.world(1.5,.13,1.2);var rider=new ArmorStand(h.getLevel(),point.x,point.y,point.z);rider.setNoGravity(true);h.getLevel().addFreshEntity(rider);check(d.requestFloor(base+12),"Rear-only destination accepted");
  var first=new net.neoforged.neoforge.common.util.FakePlayer(h.getLevel(),new com.mojang.authlib.GameProfile(UUID.randomUUID(),"elevator-rider-one"));var second=new net.neoforged.neoforge.common.util.FakePlayer(h.getLevel(),new com.mojang.authlib.GameProfile(UUID.randomUUID(),"elevator-rider-two"));h.getLevel().addNewPlayer(first);h.getLevel().addNewPlayer(second);first.setNoGravity(true);second.setNoGravity(true);var p1=e.world(.8,.13,1.8);var p2=e.world(2.1,.13,1.8);first.setPos(p1.x,p1.y,p1.z);second.setPos(p2.x,p2.y,p2.z);
  boolean[] saved={false},arrived={false};
  h.onEachTick(()->{
   var s=d.model().state();if(s==null)return;
   if(s.state()==CabinMotionController.State.FAULT)throw new GameTestAssertException(s.fault());
   if(s.state()==CabinMotionController.State.MOVING){check(e.doorsClosed(),"Cabin doors locked throughout movement");check(Math.abs(rider.getY()-(e.getY()+.13))<.03,"Server rider follows physical floor");check(Math.abs(first.getY()-(e.getY()+.13))<.03&&Math.abs(second.getY()-(e.getY()+.13))<.03,"Two server-player riders move with the cabin floor");if(!saved[0]&&Objects.equals(s.target(),base+12)){var tag=d.model().save();var copy=new ModelCabinController(d);copy.load(tag);check(copy.state().target().equals(base+12)&&copy.config().equals(d.model().config()),"Moving controller/configuration persist");saved[0]=true;}}
   if(s.state()==CabinMotionController.State.DOORS_OPEN&&Math.abs(s.y()-(base+12))<.001&&!arrived[0]){check(!e.configuration().rearGlass(),"Rear glazing removed for rear doors");check(e.front(1)==0,"Front stays shut at rear-only floor");check(d.requestFloor(base),"Downward return queued");arrived[0]=true;}
   if(arrived[0]&&s.state()==CabinMotionController.State.DOORS_OPEN&&Math.abs(s.y()-base)<.001){check(saved[0],"Travel snapshot checked");rider.discard();first.discard();second.discard();h.succeed();}
  });
 }
